-- Guarded cleanup of inert legacy resource child pools, batch 12.
-- Physical gameobject rows are untouched.
START TRANSACTION;
DELETE pp FROM pool_pool pp LEFT JOIN pool_creature pc ON pc.pool_entry=pp.pool_id LEFT JOIN pool_gameobject pg ON pg.pool_entry=pp.pool_id LEFT JOIN pool_quest pq ON pq.pool_entry=pp.pool_id LEFT JOIN game_event_pool gep ON gep.pool_entry=pp.pool_id LEFT JOIN pool_pool child ON child.mother_pool=pp.pool_id WHERE pp.pool_id IN (2663,2671,2674,2675,2682,2688,2690,2692,2706,2708,2711,2719,2729,2736,2739,2744,2755,2762,2764,2774,2781,2783,2793,2796,2802,2812,2822,2823,2825,2832,2834,2836,2839,2842,2850,2852,2853,2857,2858,2859,2860,2861,2862,2863,2864,2865,2866,2867,2868,2869) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND child.pool_id IS NULL;
DELETE pt FROM pool_template pt LEFT JOIN pool_creature pc ON pc.pool_entry=pt.entry LEFT JOIN pool_gameobject pg ON pg.pool_entry=pt.entry LEFT JOIN pool_quest pq ON pq.pool_entry=pt.entry LEFT JOIN game_event_pool gep ON gep.pool_entry=pt.entry LEFT JOIN pool_pool pp_child ON pp_child.pool_id=pt.entry LEFT JOIN pool_pool pp_mother ON pp_mother.mother_pool=pt.entry WHERE pt.entry IN (2663,2671,2674,2675,2682,2688,2690,2692,2706,2708,2711,2719,2729,2736,2739,2744,2755,2762,2764,2774,2781,2783,2793,2796,2802,2812,2822,2823,2825,2832,2834,2836,2839,2842,2850,2852,2853,2857,2858,2859,2860,2861,2862,2863,2864,2865,2866,2867,2868,2869) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND pp_child.pool_id IS NULL AND pp_mother.pool_id IS NULL;
COMMIT;

